      ],
      "key":"gtl_language_role",
      "label":"GTL role"
    },
    {
      "conditions": [],
      "definition": "ABG is the singular traversal-governance and runtime-truth role. Its owned operations and facts include traversal, dispatch, actor invocation, process supervision, graph-call realisation, runtime facts, event emission/replay, frames, continuations, retry/correction control, closure folds, re-entry after publish boundaries, lineage and provenance. This describes source-defined authority, not an authority granted by this interpretation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":585,
          "quote":"ABG owns traversal; dispatch; actor invocation; process supervision;\ngraph-call realisation; runtime facts; runtime event emission and replay;\nframes; continuations; retry and correction control; closure folds over\nruntime truth; re-entry after publish boundaries; lineage and provenance\n(P6).",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is%2FABG",
