      "exceptions": [],
      "grounding": [
        {
          "end_line":547,
          "quote":"App\n= Bootstrap Surface\n+ Initialization Surface\n+ Domain Configuration\n+ Typed Domain Assets / Nodes\n+ GTL Function Catalog\n+ GTL Module\n+ Policy Hook Bindings\n+ ABG Runtime\n+ Projection / Query Surface\n+ Proof Surface",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ODD.md#ODD%2F10.%20What%20an%20ODD%20product%20is",
          "start_line":537
        },
        {
