    {
      "conditions": [],
      "definition": "A lawful admissible transition between nodes. Its declaration gives required upstream assets, target asset, governing evaluators/gates and output contract; the probabilistic-work boundary additionally declares required context, role/capability expectation, provenance obligation and lawful stop, hold, gap, continuation or completion states.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":290,
          "quote":"Vectors are the lawful transitions between nodes and are the admissible\ntransitions of the product. Each vector declares its required upstream\nassets, its target asset, its governing evaluators and gates, and its\noutput contract (P4a, P6).",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ODD.md#ODD%2F5.%20Graph%20model%2FVectors",
          "start_line":287
        },
        {
          "end_line":315,
          "quote":"The vector declares the admissible external traversal space: required\nupstream assets; target asset or output contract; required context; role\nor capability expectation; governing evaluators and gates; provenance\nobligation; and the lawful stop, hold, gap, continuation or completion\nstates.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ODD.md#ODD%2F5.%20Graph%20model%2FProbabilistic%20compute",
