      "exceptions": [],
      "grounding": [
        {
          "end_line":330,
          "quote":"- `F_P` (`urn:stdo:concept:graph-native-odd:f-p`) is the shorthand for the\n  bounded probabilistic worker turn. It specialises substrate-neutral\n  lawful probabilistic processing: it keeps bounded non-human construction\n  under declared policy and narrows that meaning to one graph traversal\n  contract.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ODD.md#ODD%2F5.%20Graph%20model%2FProbabilistic%20compute",
