      "grounding": [
        {
          "end_line":340,
          "quote":"- `F_H` (`urn:stdo:concept:graph-native-odd:f-h`) is the shorthand for\n  explicit human adjudication invoked under the traversal's declared\n  authority and ambiguity policy. It specialises the substrate-neutral\n  human-adjudication concept and grants a human no ambient traversal,\n  semantic or closure authority.",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/ODD.md#ODD%2F5.%20Graph%20model%2FProbabilistic%20compute",
